        #region EggQuest
        [NpcAttribute(NpcID.EggQuest)]
        private static void EggQuest(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        dialog.AddText("I can exchange your egg for random rewards.\n")
                              .AddOption("I want to exchange.", 1)
                              .AddOption("Just passing by.")
                              .AddAvatar(3).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        // Verifica se o jogador tem pelo menos 1 Egg (exemplo ID: 710002)
                        if (client.Inventory.Contain(710002, 1))
                            {
                            // Remove 1 Egg
                            client.Inventory.Remove(710002, 1, stream);

                            string rewardName = "";

                            // Sorteia item aleatório
                                switch (Program.GetRandom.Next(1, 6))
                            {
                                case 1:
                                    client.Inventory.Add(stream, ItemType.Meteor, 3);
                                    rewardName = "3 Meteor";
                                    break;

                                case 2:
                                    client.Inventory.Add(stream, ItemType.Meteor, 3);
                                    rewardName = "3 Meteor";
                                    break;

                                case 3:
                                    client.Inventory.Add(stream, ItemType.ExpBall, 1);
                                    rewardName = "1 ExpBall";
                                    break;

                                case 4:
                                    client.Inventory.Add(stream, ItemType.DragonBall, 1);
                                    rewardName = "1 DragonBall";
                                    break;

                                case 5:
                                    {
                                        // Arrays separados por categoria (IDs como uint)
                                        uint[] helmets = { 111005, 111006, 111008, 113004, 113035, 114003, 114006, 114008, 114025, 114028, 142003 };   // CloudCap +1
                                        uint[] armors = { 130003, 130003, 130008, 130063, 130013, 131002, 131073, 133003, 133043, 133028, 133033 };   // Armor +1
                                        uint[] swords = { 420023, 420033, 420050, 420058, 420070, 420023, 420023 };   // Sword +1
                                        uint[] TaoRobe = { 134003, 134008, 134063, 134003, 134025, 134030 };   // TaoRobe +1
                                        uint[] bows = { 500013, 500043, 500013, 500043, 500046, 500113, 500173, 500053, 500043, 500013 };   // Bow +1
                                        uint[] Headband = { 141003, 141023, 141028, 141093 };   // Headband +1
                                        uint[] clubs = { 480003, 480003, 480008, 480023, 480023, 480070, 480133, 480166 };   // Club +1
                                        uint[] BackSword = { 421023, 421028, 420042, 421080, 421100, 421143, 421148, 421023 };   // BackSword +1
                                        uint[] blades = { 410023, 410080, 410088, 410023, 410050, 410080 };   // Blade +1
                                        uint[] wands = { 561023, 561023, 561043, 561110, 561136, 580023, 580033, 580133 };   // Wand e Halbert +1
                                        uint[] sceptres = { 481023, 481023, 481100, 481070, 481068 };   // Sceptre +1
                                        uint[] Dagger = { 490023, 490043, 490023, 490043, 481068, 490068, 490060 };   // Dagger +1
                                        uint[] glaives = { 510023, 510050, 510023, 510058, 510223 };   // Glaive +1
                                        uint[] Hook = { 430050, 430060, 430070, 430048 };   // Hook +1
                                        uint[] Whip = { 440023, 440060, 440076, 440090 };   // Whip +1
                                        uint[] Axe = { 450023, 450050, 450090, 450066, 530023, 530100, 530106, 530173 };   // Axe e Poleaxe +1
                                        uint[] LongHammer = { 540023, 540033, 540023, 540143, 540177 };   // LongHammer +1
                                        uint[] shields = { 900010, 900020, 900020, 900033, 900048, 900043, 900073 };   // Shield +1
                                        uint[] Spear = { 560023, 560023, 560080, 560088, 560023 };   // Spear +1
                                        uint[] boots = { 160013, 160018, 160033, 160070 };   // Boots +1
                                        uint[] necklaces = { 120003, 120003, 120008, 120080, 120090 };   // Necklace +1
                                        uint[] rings = { 150003, 150008, 150033, 150153, 151013, 151018, 151173 };   // Ring +1
                                        uint[] bracelets = { 152013, 152016, 152080, 152163 };   // Bracelet +1
                                        uint[] Earring = { 117003, 117008, 117075, 117078 };   // Earring +1
                                        uint[] Coronet = { 118003, 118008, 118023, 118028 };   // Coronet +1
                                        uint[] Bag = { 121023, 121023, 121028, 121153, 121153, 121158, 121183, 121183 };   // Bag +1

                                        // Junta todas as categorias
                                        List<uint[]> categories = new List<uint[]>
        { helmets, armors, swords, bows, clubs, blades, wands, sceptres, glaives, shields, boots, necklaces, rings, bracelets, Earring, Coronet, Bag, TaoRobe, Headband, BackSword, Hook, Whip, Axe, LongHammer, Dagger, Dagger };

                                        // Sorteia uma categoria
                                        uint[] chosenCategory = categories[Program.GetRandom.Next(0, categories.Count)];

                                        // Sorteia um item dentro da categoria escolhida
                                        uint chosenId = chosenCategory[Program.GetRandom.Next(0, chosenCategory.Length)];

                                        // Adiciona o item +1 sorteado no inventário.
                                        client.Inventory.Add(stream, chosenId, 1, 1, 0, 0, 0);

                                        rewardName = "Item +1";
                                        break;
                                    }

                            }

                            // Sorteia Silver (5000 ou 9500)
                            int silverReward = 5000;
                            if (Program.GetRandom.Next(0, 100) < 20) // 20% de chance de ser 9500
                                silverReward = 9500;

                            client.Player.Money += (uint)silverReward;
                            client.Player.SendUpdate(stream, client.Player.Money, Game.MsgServer.MsgUpdate.DataType.Money);

                            // Mensagem para o jogador
                            dialog.AddText("You exchanged your Egg!")
                                  .AddOption("Thanks", 255)
                                  .AddAvatar(3).FinalizeDialog();

                            // Mensagem global
                            Program.SendGlobalPackets.Enqueue(
                                new Game.MsgServer.MsgMessage($"Player: [{client.Player.Name}] has claimed {rewardName} in NPC (egg).",
                                Game.MsgServer.MsgMessage.MsgColor.white,
                                Game.MsgServer.MsgMessage.ChatMode.TopLeft).GetArray(stream));
                        }
                        else
                        {
                            dialog.AddText("You don’t have an Egg.\n")
                                  .AddOption("Ok.", 255)
                                  .AddAvatar(3).FinalizeDialog();
                        }
                        break;
                    }
            }
        }


