        [NpcAttribute(NpcID.ExtremeFlagOut)]
        public static void ExtremeFlagOut(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
