                            .AddOption("Just~passing~by", 255)
                            .AddAvatar(6)
                            .FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        if (client.Inventory.SearchItemByID(721536, 1, out var diamondItems))
                        {
                            if (client.Inventory.HaveSpace(1))
                            {
                                // Remove o Diamond
                                client.Inventory.Remove(721536, 1, stream);

                                // Lista de prêmios possíveis IDs
                                uint[] prizeList = new uint[]
                                {
                723792, 721080, 182705, 194295, 710562, 181110, 194265, 194185, 194155,
                193715, 193705, 193665, 187705, 183815, 199675, 188285,
                720028, 721080, 182705, 723792, 721080, 1200006, 182705, 721259, 721080, 700013, 182705, 700003, 720028, 723792
                                };

                                // Sorteio aleatório
                                Random rnd = new Random();
                                uint prize = prizeList[rnd.Next(prizeList.Length)];

