                case 11:
                case 21:
                case 41:
                case 132:
                case 142:
                case 51:
                    {

                        if (!client.Inventory.HaveSpace(4))
                        {
                            data.AddText("Sorry, but you need at least 4 free spaces in your inventory.")
                                .AddOption("I~see.", 255)
