        [NpcAttribute(NpcID.StartNpc)]
        public static void StartNpc(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog dialog = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        dialog.Text("Welcome to Conquer Classic 1.0 \n");
                        dialog.Text("Do you wish to be teleported to Twincity ?\n");
                        dialog.Option("Teleport~me", 1);
                        dialog.Option("Just~passing~by", 0);
                        dialog.AddAvatar(71).FinalizeDialog();
                        break;
                    }
                case 1:
                    {
                        client.Inventory.Add(stream, 1000000, 3, 0, 0, 0, 0, 0, false);
                        client.Inventory.Add(stream, 132003, 1, 0, 0, 0, 0, 0, false);
                        client.Inventory.Add(stream, 410003, 1, 0, 0, 0, 0, 0, false);

                        if ((client.Player.Class >= 50 && client.Player.Class <= 55) ||
                            (client.Player.Class >= 60 && client.Player.Class <= 65))
                        {
                            dialog.Text("Blocked-Class");
                            dialog.Option("Ok", 0);
                            dialog.AddAvatar(71).FinalizeDialog();
                        }
                        else
                        {
                            client.Teleport(428, 378, 1002);

                            client.Player.VipLevel = 6;
                            client.Player.ExpireVip = DateTime.Now.AddDays(1);
                        }
                        break;
                    }
            }
        }


