                            client.Inventory.Remove(751999, 1, stream);
                            client.Player.Money += 200000;

                            data.AddText("You received 200,000 silver.")
                                .AddOption("Thanks", 255)
                                .FinalizeDialog();
                        }
                        else
                        {
                            data.AddText("Sorry, but you don't have 999RedRoses.")
                                .AddOption("Ok", 255)
                                .FinalizeDialog();
                        }
                        break;
                    }
            }
        }


        [NpcAttribute(NpcID.ProfCompose)]
        public static void ProfCompose(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("Choose whether you want to exchange your Prof Pack. \n");
                        data.AddText("Choose whether you want to compose using 20 Prof Tokens.")
                            .AddOption("[ Change Pack ]", 1)
                            .AddOption("[ Compose ]", 2)
                            .AddOption("Just~passing~by.", 255)
                            .AddAvatar(6)
                            .FinalizeDialog();
                        break;
                    }

                case 1:
                    {
                        if (client.Inventory.Contain(710562, 1))
                        {
                            if (client.Inventory.HaveSpace(20))
                            {
                                client.Inventory.Remove(710562, 1, stream);

                                client.Inventory.Add(stream, 710001, 20, 0, 0, 0,
                                    Role.Flags.Gem.NoSocket, Role.Flags.Gem.NoSocket, false);

                                data.AddText("You received the 20 ProfTokens.")
                                    .AddOption("Thanks", 255)
                                    .AddAvatar(6)
                                    .FinalizeDialog();
                            }
                            else
                            {
                                data.AddText("You don't have space in your inventory.")
                                    .AddOption("Ok", 255)
                                    .AddAvatar(6)
                                    .FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("You do not have 1 Prof Pack.")
                                .AddOption("Ok", 255)
                                .AddAvatar(6)
                                .FinalizeDialog();
                        }
                        break;
                    }

                case 2:
                    {
                        if (client.Inventory.Contain(710001, 20))
                        {
                            if (client.Inventory.HaveSpace(1))
                            {
                                client.Inventory.Remove(710001, 20, stream);

                                client.Inventory.Add(stream, 710562, 1, 0, 0, 0,
                                    Role.Flags.Gem.NoSocket, Role.Flags.Gem.NoSocket, false);

                                data.AddText("You received 1 ProfToken Pack.")
                                    .AddOption("Thanks", 255)
                                    .AddAvatar(6)
                                    .FinalizeDialog();
                            }
                            else
                            {
                                data.AddText("You don't have space in your inventory.")
                                    .AddOption("Ok", 255)
                                    .AddAvatar(6)
                                    .FinalizeDialog();
                            }
                        }
                        else
                        {
                            data.AddText("You do not have 20 ProfTokens.")
                                .AddOption("Ok", 255)
                                .AddAvatar(6)
                                .FinalizeDialog();
                        }
                        break;
                    }
            }
        }


        [NpcAttribute(NpcID.ArtisanBird)]
        public static void ArtisanBird(Client.GameClient client, ServerSockets.Packet stream, byte Option, string Input, uint id)
        {
            Dialog data = new Dialog(client, stream);
            switch (Option)
            {
                case 0:
                    {
                        data.AddText("First and second sockets require 5 dragonballs each.")
                            .AddOption("Primary Weapon.", 14)
                            .AddOption("Secondary Weapon.", 15)
                            .AddOption("Just~passing~by.", 255)
                            .AddAvatar(3)
                            .FinalizeDialog();
                        break;
                    }
                case 14:
                case 15:
                    {
                        MsgServer.MsgGameItem DataItem;
                        if (client.Equipment.TryGetEquip((Role.Flags.ConquerItem)(Option - 10), out DataItem))
                        {
                            if (DataItem != null)
                            {
                                ushort Position = Database.ItemType.ItemPosition(DataItem.ITEM_ID);

                                if (Database.ItemType.IsArrow(DataItem.ITEM_ID))
                                {
                                    client.SendSysMesage("Sorry, this item isn't allowed.");
                                    return;
                                }

                                if (Database.ItemType.AllowToUpdate((Role.Flags.ConquerItem)Position))
                                {
                                    var itemLevel = Database.Server.ItemsBase[DataItem.ITEM_ID].Level;

                                    if (itemLevel > client.Player.Level)
                                    {
                                        client.SendSysMesage("You cannot open a socket on this item because its level is higher than your character level.");
                                        return;
                                    }

                                    if (Option == 14 || Option == 15)
                                    {
                                        if (DataItem.SocketOne == Role.Flags.Gem.NoSocket)
                                        {
                                            if (client.Inventory.Contain(Database.ItemType.DragonBall, 5))
                                            {
                                                DataItem.SocketOne = Role.Flags.Gem.EmptySocket;
                                                DataItem.Mode = Role.Flags.ItemMode.Update;
                                                DataItem.Send(client, stream);
                                                if (DataItem.Position != 0)
                                                    client.Equipment.QueryEquipment();
                                                client.Inventory.Remove(Database.ItemType.DragonBall, 5, stream);
                                                client.SendSysMesage("First socket opened successfully!");
                                            }
                                            else
                                            {
                                                client.SendSysMesage("Sorry, you don't have 5 DragonBall!");
                                            }
                                        }
                                        else if (DataItem.SocketTwo == Role.Flags.Gem.NoSocket)
                                        {
                                            if (client.Inventory.Contain(Database.ItemType.DragonBall, 5))
                                            {
                                                DataItem.SocketTwo = Role.Flags.Gem.EmptySocket;
                                                DataItem.Mode = Role.Flags.ItemMode.Update;
                                                DataItem.Send(client, stream);
                                                if (DataItem.Position != 0)
                                                    client.Equipment.QueryEquipment();
                                                client.Inventory.Remove(Database.ItemType.DragonBall, 5, stream);
                                                client.SendSysMesage("Second socket opened successfully!");
                                            }
                                            else
                                            {
                                                client.SendSysMesage("Sorry, you don't have 5 DragonBalls!");
                                            }
                                        }
                                        else
                                        {
                                            client.SendSysMesage("This item already has 2 sockets.");
                                        }
                                    }
                                }
                            }
                        }
                        break;
                    }

            }
        }
    }
}